<?php
declare(strict_types=1);namespace Liberu\Accounting\FixedAssets\Actions;use Liberu\Accounting\FixedAssets\Exceptions\InvalidAsset;use Liberu\Accounting\FixedAssets\Models\AssetCategory;final class CreateCategory {public function handle(array $a):AssetCategory{foreach(['category_ref','name','asset_account_ref','depreciation_account_ref','useful_life_months','depreciation_method']as$k)if(blank($a[$k]??null))throw new InvalidAsset("Missing category field [{$k}].");if((int)$a['useful_life_months']<1)throw new InvalidAsset('Useful life must be positive.');return AssetCategory::create(['team_id'=>$a['team_id']??null,'category_ref'=>$a['category_ref'],'name'=>$a['name'],'asset_account_ref'=>$a['asset_account_ref'],'depreciation_account_ref'=>$a['depreciation_account_ref'],'useful_life_months'=>$a['useful_life_months'],'depreciation_method'=>$a['depreciation_method'],'metadata'=>$a['metadata']??null]);}}
